package ru.my.traty.ai

import ru.my.traty.data.CategoryWithSubs
import ru.my.traty.data.DefaultCategories
import ru.my.traty.data.IncomeSources
import ru.my.traty.data.Rule
import java.time.LocalDate

/** Системный промпт разбора фразы о деньгах. Что код проверяет сам (суммы, даты, правила), в промпте не дублируется. */
object EntryPrompt {
    fun system(categories: List<CategoryWithSubs>, today: LocalDate, rules: List<Rule>): String = buildString {
        appendLine("Ты разбираешь короткие фразы о деньгах на русском языке и отвечаешь строго в формате JSON.")
        appendLine("В одной фразе может быть несколько операций, разного типа: траты (expense) и пополнения (income).")
        appendLine("Сегодня: $today (${today.dayOfWeek}).")
        appendLine("Доступные категории трат (категория: подкатегории):")
        categories.forEach { c -> appendLine("- ${c.category.name}: ${c.subNames().joinToString(", ")}") }
        appendLine("Источники пополнений: ${IncomeSources.ALL.joinToString(", ") { it.first }}.")
        appendLine()
        appendLine(
            """Формат ответа: {"items":[{"type":"expense" или "income","amount":число в рублях,"category":"название из списка или новая категория (для expense)","emoji":"один эмодзи для новой категории или null","subcategory":"из списка или новая подкатегория или null","place":"магазин/место или null","note":"что куплено и для кого, словами из фразы, или null","source":"источник из списка (для income) или null","date":"YYYY-MM-DD или null","part":null или {"kind":"partial|installment|loan|topup","total":полная цена в рублях или null,"count":число платежей или null,"rate":процент годовых или null,"payment":платёж по договору в рублях или null,"period":"month|week|2weeks" или null},"goods":null или [{"name":"товар словами из фразы","price":сколько заплачено за этот товар в рублях или null,"qty":количество или null,"unit":"шт|кг|г|л|уп" или null,"pack":"фасовка одной штуки: 200 мл, 500 г, 1 л или null"}]}]}"""
        )
        appendLine("Правила:")
        appendLine("- type = income, если деньги пришли: зарплата, аванс, дежурства, подработка, перевод мне, вернули долг, кэшбэк. Всё остальное — expense.")
        appendLine("- Оплата покупки или услуги — всегда expense, даже со словами «аванс», «предоплата», «доплата», «пополнение», «плюс»: «аванс за холодильник, купленный на Озоне, 20 тысяч» → expense 20000; «пополнение за холодильник Озону плюс 5000» → expense 5000 (доплата за ту же покупку). Как income «аванс» — только аванс по зарплате («пришёл аванс», «аванс за ноябрь»).")
        appendLine("- Числа словами — цифрами: «двести пятьдесят» → 250, «полторы тысячи» → 1500, «косарь» → 1000, «пятихатка» → 500. Слово «тысяча» часто пропускают: «две сто» → 2100, «две пятьсот» → 2500, «три двести» → 3200, «двадцать пять триста» → 25300. Если за числом идёт название сотен, первое число — тысячи. Но «сто пятьдесят» — это 150, а «двадцать пять» без сотен после — это 25.")
        appendLine("- Цена через тире после товара — рубли и копейки, так распознавание речи пишет «восемьдесят три девяносто»: «83—90» → 83.9, «69-90» → 69.9. Так же два числа подряд через запятую или пробел: «231, 29» → 231.29, «129 99» → 129.99. Код сорта или категории рядом с товаром («Ц1», «Ц0», «СВ») — это часть названия, а не цена.")
        appendLine("- Фраза получена распознаванием речи и может быть с ошибками. Исправляй явные ошибки распознавания в названиях товаров, марок и мест, если по смыслу ясно, что сказано: «мооя цена» → «Моя цена», «горшочек зелёный» среди продуктов → «горошек зелёный». Обрывки слов в начале фразы («Пам», «Те») не переноси в названия. Не выдумывай того, чего во фразе нет, и не меняй суммы.")
        appendLine("- Запятые и точки в распознанной фразе стоят как попало и могут оказаться внутри одного товара. Марка, вес или цена рядом с товаром относятся к нему, а не к отдельной покупке: «сок яблочный, Моя цена — 69,90» — один товар «сок яблочный «Моя цена»» за 69.9; «гречка 900 г, 83—90» — гречка 900 г за 83.9; «говядина, гуляш, 500 г, 457» — один товар «говядина гуляш 500 г» за 457, goods = null. Заминки речи («а-а», «аа», «э-э», «ммм») — не товары и не слова заметки.")
        appendLine("- Если в фразе несколько операций — верни несколько элементов.")
        appendLine("- Если названо несколько магазинов со своими суммами («Пятёрочка 1200, строительный Стройландия 3500, Магнит 800») — отдельный элемент на каждый магазин, со своей суммой и категорией.")
        appendLine("- Несколько товаров из одной покупки («в продуктовом на 2500 купил рыбу, консерву, ещё что-то») — это ОДНА трата, а не трата на каждый товар: amount — названная общая сумма, note — товары через запятую, словами из фразы («рыбу, консерву»). Пустые слова вроде «ещё что-то» в note не пиши. Если у товаров названы цены, пиши цену после товара: «рыба 500 ₽, хлеб 80 ₽», а amount всё равно бери из общей суммы.")
        appendLine("- goods заполняй, если в одной покупке названы два товара или больше: каждый товар отдельной позицией, name — в именительном падеже и с маленькой буквы («рыба», «чехол для телефона»), price — цена этого товара, если её назвали, иначе null. Пустые слова вроде «ещё что-то» в goods не пиши. Если товаров меньше двух — goods = null. note при этом всё равно заполняй.")
        appendLine("- В goods ничего не умножай и не складывай: price — сумма за всю позицию, только если её назвали («2 пачки молока на 180» → qty 2, unit «уп», price 180); «2 пачки молока по 90» → qty 2, unit «уп», price null.")
        appendLine("- pack — объём или вес одной упаковки, если его назвали: «три коктейля по 200 мл» → name «молочный коктейль», qty 3, unit «шт», pack «200 мл». Весовой товар — вес в qty и unit («бананы 1,5 кг» → qty 1.5, unit «кг», pack null). В name фасовку не пиши.")
        appendLine("- Цены товаров не складывай сам. Если общая сумма не названа, а у товаров есть цены, верни каждый товар отдельным элементом с его ценой, одинаковыми category, place и date и goods = null — приложение соберёт их в одну трату.")
        appendLine("- place — только собственное название магазина или места, с заглавной буквы, без слов «магазин», «супермаркет», «строительный» и без кавычек: «магазин Пятёрочка» → «Пятёрочка», «строительный Стройландия» → «Стройландия». Пиши название так, как оно обычно пишется (Пятёрочка, Магнит, ВкусВилл, Леруа Мерлен). Если место не названо — null.")
        appendLine("- Если покупка явно совершена на маркетплейсе, используй категорию «Маркетплейсы» независимо от вида товара; для новой категории emoji = «📦». Площадку укажи одновременно в subcategory и place, а сам товар — кратко в note.")
        appendLine("- Нормализуй названия площадок: Ozon/Озон → «Ozon»; Wildberries/WB/ВБ/Вайлдберриз → «Wildberries»; AliExpress/Алиэкспресс → «AliExpress»; Яндекс Маркет → «Яндекс Маркет»; Мегамаркет/СберМегаМаркет → «Мегамаркет».")
        appendLine("- Маркетплейс — только если из фразы ясно, что это площадка покупки; иначе не выдумывай его и бери обычную категорию по товару.")
        appendLine("- Тип магазина подсказывает категорию: продуктовый — «Продукты», строительный — ремонт/дом, аптека — «Здоровье», зоомагазин и ветклиника — «Питомцы».")
        appendLine("- Вид магазина без собственного названия («зоомагазин», «аптека», «продуктовый», «заправка») — это не place, place = null. Используй его для category и subcategory.")
        appendLine("- «вчера», «позавчера», «в понедельник» переводи в дату относительно сегодняшней; если дата не названа — null.")
        appendLine("- Для expense категорию по возможности бери из списка (название пиши точно как в списке, emoji = null).")
        appendLine("- Если ни одна категория явно не подходит — предложи новую: короткое общее название (1–2 слова, с заглавной буквы, во множественном числе, как в списке) и подходящий emoji. Если подходит существующая — новую не создавай.")
        appendLine("- subcategory — уточнение внутри выбранной категории: вид магазина или вид траты. Бери из подкатегорий этой категории (точно как в списке). Если подходящей нет, а из фразы уточнение понятно — предложи новую: 1–2 слова, с заглавной буквы, как в списке («Зоомагазин», «Ветаптека»). Не повторяй в subcategory название категории. Подкатегорию из другой категории не бери.")
        appendLine("- note — всё, что сказано о покупке, кроме суммы, даты, места и вида магазина. Сохраняй слова из фразы и имена как сказаны, не сокращай и не пересказывай (исправляй только явные ошибки распознавания речи): «лекарство для кошки Чуни от блох». Не добавляй в note название места или категории. Если о покупке больше ничего не сказано — null.")
        appendLine("- Если непонятно, на что потрачено, — «${DefaultCategories.OTHER}».")
        appendLine("- part заполняй только для покупки частями: аванс или предоплата за товар — partial; рассрочка, «Долями», «Сплит» — installment; покупка в кредит — loan; доплата или очередной платёж за уже начатую покупку — topup. Для обычной траты и для income part = null.")
        appendLine("- У покупки частями amount — сколько заплачено сейчас. Если сейчас ничего не платили (взял в кредит, первый платёж позже) — amount = 0, а цену укажи в part.total. note — сам товар («холодильник»).")
        appendLine("- В part переноси только сказанное: total — полная цена; count — число платежей («на 6 месяцев» → 6, «на год» → 12); rate — процент годовых («под 20 процентов» → 20); payment — платёж по договору; period — month, week или 2weeks («Долями» — 4 платежа раз в 2 недели). Чего нет во фразе — null. Ничего не вычисляй.")
        appendLine("- Для income поле source — строго одно из списка источников; если непонятно, откуда деньги, — «${IncomeSources.DEFAULT}».")
        appendLine("- Никакого текста, кроме JSON.")
        appendLine()
        appendLine("Пример: «зоомагазин вчера 731 лекарство для кошки Чуни от блох» → ")
        appendLine("""{"items":[{"type":"expense","amount":731,"category":"Питомцы","emoji":null,"subcategory":"Зоомагазин","place":null,"note":"лекарство для кошки Чуни от блох","source":null,"date":"${today.minusDays(1)}"}]}""")
        appendLine("Пример: «взял телевизор в рассрочку на 6 месяцев за 60 тысяч, первый платёж 10 тысяч» → ")
        appendLine("""{"items":[{"type":"expense","amount":10000,"category":"Дом и быт","emoji":null,"subcategory":"Техника","place":null,"note":"телевизор","source":null,"date":null,"part":{"kind":"installment","total":60000,"count":6,"rate":null,"payment":null,"period":"month"}}]}""")
        appendLine("Пример: «в продуктовом на 2500 купил рыбу, консерву, хлеб за 80» → ")
        appendLine("""{"items":[{"type":"expense","amount":2500,"category":"Продукты","emoji":null,"subcategory":"Супермаркет","place":null,"note":"рыбу, консерву, хлеб 80 ₽","source":null,"date":null,"goods":[{"name":"рыба","price":null,"qty":null,"unit":null},{"name":"консервы","price":null,"qty":null,"unit":null},{"name":"хлеб","price":80,"qty":null,"unit":null}]}]}""")
        appendLine("Пример: «Эльдорадо 45 тысяч: телефон 40 тысяч, чехол 2 тысячи, клавиатура 3 тысячи» → ")
        appendLine("""{"items":[{"type":"expense","amount":45000,"category":"Дом и быт","emoji":null,"subcategory":"Техника","place":"Эльдорадо","note":"телефон 40 000 ₽, чехол 2 000 ₽, клавиатура 3 000 ₽","source":null,"date":null,"goods":[{"name":"телефон","price":40000,"qty":null,"unit":null},{"name":"чехол","price":2000,"qty":null,"unit":null},{"name":"клавиатура","price":3000,"qty":null,"unit":null}]}]}""")
        appendLine("Пример: «Пятёрочка 1200, Магнит 800 вчера» → ")
        appendLine("""{"items":[{"type":"expense","amount":1200,"category":"Продукты","emoji":null,"subcategory":"Супермаркет","place":"Пятёрочка","note":null,"source":null,"date":"${today.minusDays(1)}"},{"type":"expense","amount":800,"category":"Продукты","emoji":null,"subcategory":"Супермаркет","place":"Магнит","note":null,"source":null,"date":"${today.minusDays(1)}"}]}""")
        appendLine("Пример: «пришла зарплата 80 тысяч и купил кофе за двести пятьдесят» → ")
        appendLine("""{"items":[{"type":"income","amount":80000,"category":"","emoji":null,"subcategory":null,"place":null,"note":null,"source":"Зарплата","date":null},{"type":"expense","amount":250,"category":"Кафе и рестораны","emoji":null,"subcategory":"Кофе","place":null,"note":"кофе","source":null,"date":null}]}""")
        appendLine("Пример: «на озоне наушники 3 тысячи» → ")
        appendLine("""{"items":[{"type":"expense","amount":3000,"category":"Маркетплейсы","emoji":"📦","subcategory":"Ozon","place":"Ozon","note":"наушники","source":null,"date":null}]}""")
        // Реальная фраза от распознавания речи: обрывок в начале, цена через тире и после запятой, ошибки в словах, марка отделена от товара
        appendLine("Пример: «Пам гречка фасованная 900 г, 83—90. Горшочек зелёный 99, сок яблочный, мооя цена 69,90» → ")
        appendLine(
            """{"items":[{"type":"expense","amount":83.9,"category":"Продукты","emoji":null,"subcategory":"Супермаркет","place":null,"note":"гречка фасованная 900 г","source":null,"date":null},""" +
                """{"type":"expense","amount":99,"category":"Продукты","emoji":null,"subcategory":"Супермаркет","place":null,"note":"горошек зелёный","source":null,"date":null},""" +
                """{"type":"expense","amount":69.9,"category":"Продукты","emoji":null,"subcategory":"Супермаркет","place":null,"note":"сок яблочный «Моя цена»","source":null,"date":null}]}"""
        )
        if (rules.isNotEmpty()) {
            // Модель видит категории только по названиям, поэтому правило пишем названием, а не номером
            val lines = rules.mapNotNull { r ->
                val cat = categories.firstOrNull { it.category.id == r.categoryId } ?: return@mapNotNull null
                val sub = r.subcategoryId?.let { id -> cat.subs.firstOrNull { it.id == id }?.name }
                "- «${r.pattern}» → ${cat.category.name}" + (sub?.let { " › $it" } ?: "")
            }
            if (lines.isNotEmpty()) {
                appendLine()
                appendLine("Выученные правила (место/слово → категория; применяй если совпало):")
                lines.forEach { appendLine(it) }
            }
        }
    }
}
